package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build dynamic query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized approach for category
		query += fmt.Sprintf(" AND category = '%s'", category)
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= %s", maxPrice)
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"price": true, "name": true, "id": true}
	if sortBy != "" && allowedSorts[sortBy] {
		query += " ORDER BY " + sortBy
	} else {
		query += " ORDER BY id"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html")
	w.Header().Set("X-Content-Type-Options", "nosniff")

	fmt.Fprintf(w, "<html><body><h1>Product Search</h1>")
	fmt.Fprintf(w, "<p>Searching for: %s</p>", category)
	fmt.Fprintf(w, "<table><tr><th>ID</th><th>Name</th><th>Price</th><th>Description</th></tr>")

	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>%.2f</td><td>%s</td></tr>",
			id, name, price, description)
	}

	fmt.Fprintf(w, "</table></body></html>")
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Admin can execute raw queries for reporting
	r.ParseForm()
	rawQuery := r.FormValue("query")

	// Basic blocklist - prevent destructive operations
	lower := strings.ToLower(rawQuery)
	if strings.Contains(lower, "drop") || strings.Contains(lower, "truncate") {
		http.Error(w, "Forbidden operation", http.StatusForbidden)
		return
	}

	rows, err := db.Query(rawQuery)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "{\"status\": \"executed\"}")
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/admin/query", adminHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Server starting on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
